#!/usr/bin/env bash
# CHIM ORomance Bridge - full build without the game, Windows or Bethesda's compiler:
# what the GitHub workflow runs, and works the same on any Linux / WSL / macOS.
#
#   tools/build_linux.sh <papyrus-compiler binary> [release dir]
#
# The compiler is the open-source papyrus-compiler (github.com/russo-2025/papyrus-compiler,
# MIT); the workflow builds it from source at the commit pinned there. Instead of the
# game's script sources it type-checks against the declaration-only headers in stubs/:
# stubs/headers (generated by tools/gen_headers.py) and the hand-written ones.
# Writes build/CHIMORomanceBridge.esp, build/Scripts/*.pex and <release dir>/CHIM ORomance
# Bridge.zip (default release dir: dist/).
set -euo pipefail

COMPILER=$(realpath "${1:?usage: tools/build_linux.sh <papyrus-compiler binary> [release dir]}")
ROOT=$(cd "$(dirname "$0")/.." && pwd)
RELEASE=${2:-$ROOT/dist}
cd "$ROOT"

python3 -I make_esp.py

# one header folder: the compiler refuses two scripts of the same name in different folders
HDR=build/headers
rm -rf "$HDR" build/Scripts
mkdir -p "$HDR" build/Scripts
dupes=$(find stubs -name '*.psc' | sed 's|.*/||' | tr 'A-Z' 'a-z' | sort | uniq -d)
if [ -n "$dupes" ]; then echo "the same header in two stub folders: $dupes" >&2; exit 1; fi
find stubs -name '*.psc' -exec cp {} "$HDR"/ \;

"$COMPILER" compile -nocache -h "$HDR" -i src/Scripts/Source -o build/Scripts

for s in src/Scripts/Source/*.psc; do
  pex="build/Scripts/$(basename "$s" .psc).pex"
  test -s "$pex" || { echo "missing $pex" >&2; exit 1; }
done

python3 -I build.py "$RELEASE"
